define('taoMediaManager/controller/editInstance',['jquery', 'context', 'layout/actions/binder', 'util/url', 'taoItems/preview/inlinePropertiesPreview', 'taoMediaManager/previewer/component/qtiSharedStimulusItem', 'core/logger', 'ui/feedback', 'layout/loading-bar', 'ui/previewer'], function ($, context, binder, urlUtil, inlinePropertiesPreview, qtiItemPreviewerFactory, loggerFactory, feedback, loadingBar) {
  'use strict';

  var logger = loggerFactory('taoMediaManager/editInstance');
  var isExternalPreviewerAvailable = () => !!(context && context.previewerExternalFeUrl && context.featureFlags && context.featureFlags.FEATURE_FLAG_TAO_ADVANCE_EXTERNAL_ITEM_PREVIEWER && !context.featureFlags.FEATURE_FLAG_TAO_CG_ONLY);
  var initPreview = isPassage => {
    var $previewer = $('.previewer');
    var isPreviewEnabled = $previewer.data('enabled');
    if (!isPreviewEnabled) return;
    if (!isPassage) {
      var file = {};
      file.url = $previewer.data('url');
      file.mime = $previewer.data('type');
      file.containerClass = 'no-background';
      $previewer.previewer(file);
      return;
    }
    if (isExternalPreviewerAvailable()) {
      $previewer.attr('id', 'item-properties-preview');
      $previewer.closest('.data-container-wrapper').attr('id', 'item-properties-preview-column');
      inlinePropertiesPreview.init({
        isPreviewEnabled,
        itemUri: $('#edit-media').data('uri')
      });
      return;
    }
    loadingBar.start();
    qtiItemPreviewerFactory($previewer, {
      itemUri: $('#edit-media').data('uri')
    }).on('error', function (err) {
      if (typeof err.message !== 'undefined') {
        feedback().error(err.message);
      }
      logger.error(err);
    }).on('preview-loaded', loadingBar.stop);
  };
  var manageMediaController = {
    start() {
      var mimeType = $('.main-container').data('mimeType');
      var isPassage = mimeType === 'application/qti+xml';
      initPreview(isPassage);
      if (isPassage) {
        $('#media-authoring').show();
      } else {
        $('#media-authoring').hide();
      }
      $('#edit-media').off().on('click', function () {
        var action = {
          binding: 'load',
          url: urlUtil.route('editMedia', 'MediaImport', 'taoMediaManager')
        };
        binder.exec(action, {
          classUri: this.dataset.classuri,
          id: this.dataset.uri
        } || this._resourceContext);
      });
    }
  };
  return manageMediaController;
});
